use std::{fs::{self,OpenOptions},io::{Seek,SeekFrom,Write},path::PathBuf,time::{SystemTime,UNIX_EPOCH}};
use strata_log::{Durability,Error,Log};
fn path() -> PathBuf { std::env::temp_dir().join(format!("strata-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos())) }
#[test] fn round_trip_and_sequences(){ let p=path(); {let mut l=Log::open(&p).unwrap(); assert_eq!(l.append(&[b"one".to_vec(),vec![]],Durability::Sync).unwrap(),0); assert_eq!(l.append(&[b"two".to_vec()],Durability::Buffered).unwrap(),1); l.sync().unwrap();} let l=Log::open(&p).unwrap(); assert_eq!(l.batches()[0].records,vec![b"one".to_vec(),vec![]]); assert_eq!(l.batches()[1].sequence,1); drop(l); fs::remove_file(p).unwrap(); }
#[test] fn every_incomplete_tail_recovers(){let p=path(); {let mut l=Log::open(&p).unwrap(); l.append(&[b"first".to_vec()],Durability::Sync).unwrap(); l.append(&[b"second".to_vec(),b"third".to_vec()],Durability::Sync).unwrap();} let all=fs::read(&p).unwrap(); let first_end=8+24+4+5; for cut in first_end..all.len(){ fs::write(&p,&all[..cut]).unwrap(); let l=Log::open(&p).unwrap(); assert_eq!(l.batches().len(),1,"cut {cut}"); drop(l); assert_eq!(fs::metadata(&p).unwrap().len(),first_end as u64); } fs::remove_file(p).unwrap();}
#[test] fn complete_corruption_is_rejected(){ let p=path(); {let mut l=Log::open(&p).unwrap(); l.append(&[b"hello".to_vec()],Durability::Sync).unwrap();} let mut f=OpenOptions::new().write(true).open(&p).unwrap(); f.seek(SeekFrom::End(-1)).unwrap(); f.write_all(b"x").unwrap(); drop(f); assert!(matches!(Log::open(&p),Err(Error::Corrupt{..}))); fs::remove_file(p).unwrap(); }
#[test] fn bad_header_is_rejected(){let p=path(); fs::write(&p,b"wrong!!!").unwrap(); assert!(matches!(Log::open(&p),Err(Error::Corrupt{..}))); fs::remove_file(p).unwrap();}
